CREATE VIEW "public"."cost_summary" AS (select date_trunc('day', "layer_runs"."created_at")::date as "day", "layer_runs"."project_id", "projects"."slug" as "project_slug", "layer_runs"."locale", "layer_runs"."layer_name", "layer_runs"."kind", "layer_runs"."model", "layer_runs"."target_count", "layer_runs"."input_tokens", "layer_runs"."output_tokens", "layer_runs"."reasoning_tokens", "layer_runs"."cached_input_tokens", "layer_runs"."cost_usd", "layer_runs"."latency_ms", "layer_runs"."error", "layer_runs"."created_at" from "layer_runs" left join "projects" on "projects"."id" = "layer_runs"."project_id");